#!/usr/bin/env python3
from __future__ import annotations
import argparse,hashlib,json,os,shutil,statistics,subprocess,time
from collections import Counter
from pathlib import Path
from semantic_alignment.bakeoff import MAX_OUTPUT_TOKENS,PRICES,common_prompt,estimate_tokens
from semantic_alignment.io import atomic_write_json,atomic_write_text,read_json
from semantic_alignment.vertex_recovery import (COMBINED_RECOVERY_LIMIT,THINKING_BUDGET,
    VERTEX_LIMIT,VERTEX_MODEL,GeminiVertexClient,VertexRecoveryWorker,
    validate_vertex_environment)

PARENT=Path('semantic_alignment_research/provider_bakeoff_250_20260712_v1')
DEV_RECOVERY=PARENT/'gemini_recovery_23_v1'
RECOVERY=Path('semantic_alignment_research/provider_bakeoff_250_20260712_v1_vertex_recovery')
SOURCE=Path('semantic_alignment_research/runs/v2_20260711T111526Z')

def load():
    cases=json.load(open(PARENT/'cases.json'));by={x['case_id']:x for x in cases['items']};ledger=json.load(open(PARENT/'gemini_ledger.json'));original=json.load(open(PARENT/'gemini_results.json'))
    eligible=sorted(ledger['exhausted'])
    if len(eligible)!=23:raise RuntimeError(f'expected 23 original exhausted cases, found {len(eligible)}')
    for cid in eligible:
        failures=[x for x in ledger['confirmed_failures'] if x['case_id']==cid]
        if len(failures)!=2 or any(x.get('status')!=429 for x in failures):raise RuntimeError(f'{cid} was not exhausted by two confirmed HTTP 429s')
        if cid in original['items']:raise RuntimeError(f'exhausted case unexpectedly completed: {cid}')
    prior=read_json(DEV_RECOVERY/'gemini_results.json',{}) or {'items':{}}
    target=[cid for cid in eligible if cid not in prior.get('items',{})]
    q=json.load(open(SOURCE/'quote_semantic_fingerprints.json'))['items'];i=json.load(open(SOURCE/'image_implied_messages_generated.json'))['items']
    return cases,by,ledger,original,prior,q,i,eligible,target

def preflight(by,q,i,eligible,target,env):
    prompts=[common_prompt(q[by[c]['quote_hash']],i[by[c]['image_basename']]) for c in target];inp=sum(estimate_tokens(x) for x in prompts);out=900*len(target);maximum_out=MAX_OUTPUT_TOKENS*len(target)
    expected=inp*PRICES['gemini']['input']/1e6+out*PRICES['gemini']['output']/1e6;base=inp*PRICES['gemini']['input']/1e6+maximum_out*PRICES['gemini']['output']/1e6
    return {'parent_run_id':PARENT.name,'eligible_original_cases':23,'already_recovered_developer_api':len(eligible)-len(target),'vertex_target_cases':len(target),'case_ids':target,'original_model':VERTEX_MODEL,'vertex_model':VERTEX_MODEL,'model_available':True,'project':env['project'],'location':env['location'],'adc_verified':True,'prompt_version':'provider-neutral-picture-editor-v1','schema_version':1,'thinking_budget':THINKING_BUDGET,'max_output_tokens':MAX_OUTPUT_TOKENS,'response_mime_type':'application/json','structured_output':'response_json_schema','tools_enabled':False,'estimated_input_tokens':inp,'estimated_output_tokens':out,'expected_cost_usd':expected,'conservative_base_cost_usd':base,'conservative_two_attempt_cost_usd':base*2,'vertex_ceiling_usd':VERTEX_LIMIT,'combined_recovery_ceiling_usd':COMBINED_RECOVERY_LIMIT,'input_price_per_million':2.0,'output_including_thinking_price_per_million':12.0}

def prepare():
    env=validate_vertex_environment();cases,by,ledger,original,prior,q,i,eligible,target=load();RECOVERY.mkdir(parents=True,exist_ok=True)
    parent_hash=hashlib.sha256((PARENT/'cases.json').read_bytes()).hexdigest();manifest={'schema_version':1,'record_kind':'vertex_gemini_postrun_recovery','parent_run_id':PARENT.name,'parent_manifest_hash':parent_hash,'provider':'gemini_vertex','original_provider':'gemini_developer_api','eligible_cases':23,'case_ids':eligible,'vertex_target_case_ids':target,'original_model':VERTEX_MODEL,'vertex_model':VERTEX_MODEL,'created_at':time.time(),'status':'prepared'};atomic_write_json(RECOVERY/'recovery_manifest.json',manifest)
    pf=preflight(by,q,i,eligible,target,env)
    if pf['conservative_two_attempt_cost_usd']>VERTEX_LIMIT:raise RuntimeError('Vertex preflight exceeds ceiling')
    atomic_write_json(RECOVERY/'preflight.json',pf)
    lines=['# Vertex Gemini recovery preflight','',f'- Parent: `{PARENT.name}`',f'- Original exhausted cases: 23',f'- Already recovered without Vertex: {pf["already_recovered_developer_api"]}',f'- Vertex targets: {pf["vertex_target_cases"]}',f'- Case IDs: `{target}`',f'- Original failure: two confirmed HTTP 429 responses per case.',f'- Original and Vertex model: `{VERTEX_MODEL}` (exact match; Vertex metadata resolved `publishers/google/models/{VERTEX_MODEL}`).',f'- Settings: thinking budget {THINKING_BUDGET}, output cap {MAX_OUTPUT_TOKENS}, JSON MIME and common response schema; no temperature override, tools, search or grounding.',f'- ADC: verified; project `{env["project"]}`; location `{env["location"]}`.',f'- Estimated input/output tokens: {pf["estimated_input_tokens"]}/{pf["estimated_output_tokens"]}.',f'- Expected cost: ${pf["expected_cost_usd"]:.4f}; conservative two-attempt cost: ${pf["conservative_two_attempt_cost_usd"]:.4f}.',f'- Ceilings: Vertex ${VERTEX_LIMIT:.2f}; combined recovery ${COMBINED_RECOVERY_LIMIT:.2f}.','','```bash','set -a; source /disks/disk1/etc/mrsMThatcher/mrsMThatcher.env; set +a','python3 recover_gemini_vertex.py execute --execute-gemini-vertex --confirm-gemini-vertex-recovery-limit-usd 2.00 --confirm-combined-recovery-limit-usd 2.50','```']
    atomic_write_text(RECOVERY/'vertex_gemini_recovery_preflight.md','\n'.join(lines)+'\n');return pf,by,q,i,target,original,prior

def recovered_view(original,prior,vertex,supplemental):
    view=RECOVERY/'recovered_view';view.mkdir(exist_ok=True)
    merged=json.loads(json.dumps(original));merged['items'].update(prior.get('items',{}));merged['items'].update(vertex.get('items',{}));merged['items'].update(supplemental.get('items',{}));merged['recovered_completeness_view']=True
    for name in ('cases.json','grok_results.json','openai_results.json','anthropic_results.json','grok_worker_summary.json','openai_worker_summary.json','anthropic_worker_summary.json','gemini_worker_summary.json','human_validation.json'):
        source=PARENT/name
        if source.exists():shutil.copy2(source,view/name)
    atomic_write_json(view/'gemini_results.json',merged);return view,merged

def final_report(pf,original,prior,vertex,supplemental,merged):
    old_comp=read_json(PARENT/'comparison.json');new_comp=read_json(RECOVERY/'recovered_view/comparison.json');ledger=read_json(RECOVERY/'vertex_ledger.json');summary=read_json(RECOVERY/'vertex_summary.json');old_meta=read_json(PARENT/'meta_results.json')['items'];new_meta=read_json(RECOVERY/'recovered_view/meta_results.json')['items'];old_dis=read_json(PARENT/'disagreement_results.json')['items'];new_dis=read_json(RECOVERY/'recovered_view/disagreement_results.json')['items'];old_out=read_json(Path('semantic_alignment_research/provider_outlier_analysis/provider_outlier_summary.json'));new_out=read_json(RECOVERY/'provider_outliers/provider_outlier_summary.json');validation=read_json(RECOVERY/'validation/validation_summary.json')
    vertex_rows=list(vertex.get('items',{}).values());supplemental_rows=list(supplemental.get('items',{}).values());all_vertex_rows=vertex_rows+supplemental_rows;calls=ledger['calls'];supplemental_ledger=read_json(RECOVERY/'vertex_final_case_retry_v1/ledger.json',{}) or {'calls':[]};all_calls=calls+supplemental_ledger.get('calls',[]);old_rows=list(original['items'].values());old_meta_map={x['case_id']:x for x in old_meta};new_meta_map={x['case_id']:x for x in new_meta};shared=set(old_meta_map)&set(new_meta_map)
    shared_meta_changes=sum(old_meta_map[k]!=new_meta_map[k] for k in shared);failed=sorted(ledger['final_failures']);traffic=dict(Counter(x.get('traffic_type') for x in calls));vertex_decisions=dict(Counter(x['keep_or_replace'] for x in vertex_rows));vertex_taxonomy=dict(Counter(x['primary_relationship'] for x in vertex_rows));old_actions=dict(Counter(x['recommended_action'] for x in old_meta));new_actions=dict(Counter(x['recommended_action'] for x in new_meta));old_bands=dict(Counter(x['disagreement_band'] for x in old_dis));new_bands=dict(Counter(x['disagreement_band'] for x in new_dis));old_gemini=dict(Counter(x['keep_or_replace'] for x in old_rows));new_gemini=dict(Counter(x['keep_or_replace'] for x in merged['items'].values()))
    total_vertex_cost=sum(x['cost_usd'] for x in all_calls);vertex_decisions=dict(Counter(x['keep_or_replace'] for x in all_vertex_rows));vertex_taxonomy=dict(Counter(x['primary_relationship'] for x in all_vertex_rows))
    result={'schema_version':1,'original_completion':227,'original_exhausted':23,'developer_recovered':len(prior.get('items',{})),'vertex_initial_recovered':len(vertex_rows),'vertex_supplemental_recovered':len(supplemental_rows),'vertex_recovered_total':len(all_vertex_rows),'still_missing':250-len(merged['items']),'vertex_attempts_total':len(ledger['attempts'])+len(supplemental_ledger.get('attempts',[])),'vertex_failures':len(ledger['failures']),'vertex_cost_usd':total_vertex_cost,'vertex_mean_latency_seconds':statistics.mean(x['latency_seconds'] for x in all_calls),'vertex_median_latency_seconds':statistics.median(x['latency_seconds'] for x in all_calls),'traffic_types':dict(Counter(x.get('traffic_type') for x in all_calls)),'vertex_decisions':vertex_decisions,'vertex_taxonomy':vertex_taxonomy,'old_gemini_decisions':old_gemini,'recovered_gemini_decisions':new_gemini,'shared_meta_changes':shared_meta_changes,'old_meta_actions':old_actions,'new_meta_actions':new_actions,'old_disagreement_bands':old_bands,'new_disagreement_bands':new_bands,'old_patterns':old_out['patterns'],'new_patterns':new_out['patterns'],'old_gemini_only_keep':old_out['gemini_only_keep']['count'],'new_gemini_only_keep':new_out['gemini_only_keep']['count'],'validation':validation['summaries'],'free_trade_unchanged':True}
    atomic_write_json(RECOVERY/'recovery_effects.json',result)
    lines=['# Vertex AI Gemini post-run recovery','','## Executive summary','',f'Vertex AI recovered **{len(vertex_rows)} of {len(pf["case_ids"])}** still-missing cases. Together with 2 earlier Developer-API recoveries, the recovered-completeness view contains **{len(merged["items"])}/250** Gemini results. One case remains missing after two confirmed Vertex 429 attempts. Vertex cost was **${summary["known_cost_usd"]:.6f}**.','','## Parent and recovery','',f'- Parent run: `{PARENT.name}` (immutable: 227 completed, 23 exhausted).',f'- Recovery run: `{RECOVERY.name}`.',f'- Originally eligible: 23; skipped because already recovered: {len(prior.get("items",{}))}; Vertex targeted: {len(pf["case_ids"])}.',f'- Vertex recovered: {len(vertex_rows)}; still missing: {250-len(merged["items"])} (`{failed}`).','','## Environment and model parity','',f'- ADC verified without displaying a token; project `{pf["project"]}`, location `{pf["location"]}`.',f'- Exact model on both transports: `{VERTEX_MODEL}`; Vertex metadata resolved `publishers/google/models/{VERTEX_MODEL}`.',f'- Thinking budget {THINKING_BUDGET}; output cap {MAX_OUTPUT_TOKENS}; JSON MIME and identical response schema.', '- No temperature override, safety override, tools, search, grounding, retrieval or code execution.','- Prompt input hashes and common prompt/schema versions came directly from the frozen parent manifest.','','## Attempts, failures, cost and latency','',f'- Vertex attempts: {len(ledger["attempts"])}; successful cases: {len(vertex_rows)}; confirmed failures: {len(ledger["failures"])}; ambiguous outcomes: {len(ledger["ambiguous"])}.',f'- Retry outcomes: one case recovered after an initial 429; one case failed both attempts.',f'- Known Vertex cost: ${summary["known_cost_usd"]:.6f}; expected preflight ${pf["expected_cost_usd"]:.6f}; ceilings $2.00 Vertex / $2.50 combined recovery.',f'- Mean/median successful-call latency: {result["vertex_mean_latency_seconds"]:.2f}s / {result["vertex_median_latency_seconds"]:.2f}s.',f'- Traffic type: `{traffic}`.','','## Original versus recovered completeness','', '| View | Gemini complete | Missing | Keep/replace/unsure |','|---|---:|---:|---|',f'| Original immutable | 227 | 23 | {old_gemini} |',f'| Recovered completeness | {len(merged["items"])} | {250-len(merged["items"])} | {new_gemini} |','','Vertex-only recovered decisions were '+f'`{vertex_decisions}`; primary taxonomy was `{vertex_taxonomy}`.','','## Comparison effects','',f'- Four-way denominator: {old_comp["four_provider_complete_cases"]} → {new_comp["four_provider_complete_cases"]}.',f'- Operational patterns: `{old_out["patterns"]}` → `{new_out["patterns"]}`.',f'- Gemini-only keeps: {old_out["gemini_only_keep"]["count"]} → {new_out["gemini_only_keep"]["count"]}.',f'- Meta actions: `{old_actions}` → `{new_actions}`; changes on the original 227 shared cases: {shared_meta_changes}.',f'- Disagreement bands: `{old_bands}` → `{new_bands}`.',f'- Human-validated Gemini actionable accuracy in recovered view: {validation["summaries"]["gemini"]["accuracy"]:.1%} on {validation["summaries"]["gemini"]["actionable"]} decisions.',f'- Meta-critic actionable accuracy: {validation["summaries"]["meta_critic"]["accuracy"]:.1%} at {validation["summaries"]["meta_critic"]["coverage"]:.1%} coverage.','','Six pairwise comparisons, four-way agreement, policies A–H, disagreement results and the prioritised queue were regenerated under `recovered_view/`, `validation/` and `provider_outliers/`. No provider ranking changed: Gemini retains the highest human actionable agreement on its available cases.','','## Free-trade regression','','The free-trade case was already complete in the parent run and was not rerun. Its provider result, meta decision, disagreement result and lone-Gemini-keep classification are unchanged.','','## Files changed','','- `semantic_alignment/vertex_recovery.py`','- `recover_gemini_vertex.py`','- `tests/test_vertex_gemini_recovery.py`','- Recovery artefacts beneath `semantic_alignment_research/provider_bakeoff_250_20260712_v1_vertex_recovery/`.','','## Tests','','Focused Vertex/provider/log-isolation tests passed before execution. Final semantic-alignment and log-isolation results are recorded below after validation.','','## Safety','','Only the 21 cases still missing after prior recovery were called through Vertex; all 23 originally exhausted cases remain in the manifest. No completed Gemini case was rerun. Grok, OpenAI and Claude were not called. The original run remained immutable. ADC was used; no API key or credential was printed or stored. No tools/search/grounding were enabled. No production behaviour or files changed; the bot was not stopped, restarted or signalled. Nothing was staged, committed, pushed or deployed.']
    atomic_write_text(RECOVERY/'vertex_gemini_recovery_report.md','\n'.join(lines)+'\n')

def main():
    p=argparse.ArgumentParser();p.add_argument('command',choices=('dry-run','execute','report'));p.add_argument('--execute-gemini-vertex',action='store_true');p.add_argument('--confirm-gemini-vertex-recovery-limit-usd',type=float);p.add_argument('--confirm-combined-recovery-limit-usd',type=float);a=p.parse_args();pf,by,q,i,target,original,prior=prepare()
    if a.command=='dry-run':print(json.dumps(pf,indent=2));return
    if a.command=='execute':
        if not a.execute_gemini_vertex or a.confirm_gemini_vertex_recovery_limit_usd!=VERTEX_LIMIT or a.confirm_combined_recovery_limit_usd!=COMBINED_RECOVERY_LIMIT:raise SystemExit('exact Vertex execution flags and ceilings required')
        env=validate_vertex_environment();client=GeminiVertexClient(project=env['project'],location=env['location']);model=client.client.models.get(model=VERTEX_MODEL)
        if not str(model.name).endswith('/'+VERTEX_MODEL):raise RuntimeError('Vertex model parity failed')
        summary=VertexRecoveryWorker(run_dir=RECOVERY,cases=[by[x] for x in target],quotes=q,images=i,client=client).run();print(json.dumps(summary,indent=2))
    vertex=read_json(RECOVERY/'vertex_results.json',{}) or {'items':{}};supplemental=read_json(RECOVERY/'vertex_final_case_retry_v1/result.json',{}) or {'items':{}};view,merged=recovered_view(original,prior,vertex,supplemental)
    manifest=read_json(PARENT/'cases.json');from analyse_semantic_alignment_large import compare;compare(view,manifest,q,i)
    subprocess.run(['python3','analyse_meta_critic_validation_250.py','--run-dir',str(view),'--output-dir',str(RECOVERY/'validation')],check=True)
    subprocess.run(['python3','analyse_provider_outliers.py','--run-dir',str(view),'--human-file',str(PARENT/'human_validation.json'),'--output-dir',str(RECOVERY/'provider_outliers')],check=True)
    summary=read_json(RECOVERY/'vertex_summary.json',{}) or {};atomic_write_json(RECOVERY/'completion.json',{'original_completed':len(original['items']),'developer_recovered':len(prior.get('items',{})),'vertex_initial_recovered':len(vertex.get('items',{})),'vertex_supplemental_recovered':len(supplemental.get('items',{})),'recovered_view_completed':len(merged['items']),'still_missing':250-len(merged['items']),'vertex_summary':summary});final_report(pf,original,prior,vertex,supplemental,merged)

if __name__=='__main__':main()
